    try {
      if (currentJob) recordJob(await apiCall("GET", "/api/jobs/" + currentJob.job.id));
      else if (currentDraft) {
        const key = sessionStorage.getItem(`unio_draft_${currentDraft.id}_request`);
        const data = await apiCall("GET", "/api/jobs");
