  });
  document.addEventListener("draft-opening", () => { draftBusy = true; controls(); });
  document.addEventListener("draft-idle", () => {
    draftBusy = false;
    if (!currentJob && document.getElementById("draft-result").hidden) available.delete("prepare");
    controls();
  });
