for plan_dir in "$CONF_DIR/lib"; do
  if [ -L "$plan_dir" ] || { [ -e "$plan_dir" ] && [ ! -d "$plan_dir" ]; }; then
    echo "unio: refusing unsafe task plan directory: $plan_dir" >&2
    exit 1
  fi
done
for plan_name in task-plan.py; do
  plan_file="$CONF_DIR/lib/$plan_name"
  if [ -L "$plan_file" ] || { [ -e "$plan_file" ] && { [ ! -f "$plan_file" ] || [ "$(stat -c '%h' -- "$plan_file")" != 1 ]; }; }; then
    echo "unio: refusing unsafe task plan file: $plan_file" >&2
    exit 1
  fi
done
mkdir -p "$CONF_DIR/lib"
cat > "$CONF_DIR/lib/task-plan.py" <<'UNIO_TASK_PLAN_PY'
#!/usr/bin/env python3
# Unio — Copyright (C) 2026 Daniel Mitev
# SPDX-License-Identifier: AGPL-3.0-only; additional terms in NOTICE.
"""Bounded read-only concurrent task plan observation and recommendations.

Explains concurrent recommendations before dispatch based on an explicit
task inventory, native task markdown scopes, accepted revision evidence,
and fleet status. No executor, provider calls, queue creation or state mutation.
"""

import argparse
import datetime
import hashlib
import importlib.util
import json
import math
import os
import re
import select
import signal
import sqlite3
import stat
import subprocess
import sys
import time
from pathlib import Path

SCHEMA_VERSION = 1
MAX_INVENTORY_BYTES = 256 * 1024
MAX_TASK_FILE_BYTES = 256 * 1024
MAX_DRAFT_FILE_BYTES = 64 * 1024
MAX_DB_BYTES = 4 * 1024 * 1024
MAX_DB_ROWS = 512
MAX_TASKS = 128
MAX_ACCEPTED = 128
MAX_DEPENDENCIES = 128
OBSERVATION_DEADLINE = None


def remaining(cap):
    if OBSERVATION_DEADLINE is None:
        return cap
    return max(0.0, min(cap, OBSERVATION_DEADLINE - time.monotonic()))


def open_regular(path, limit):
    """Open every component without following links; refuse FIFOs before reads."""
    parts = Path(os.path.abspath(path)).parts
    directory = os.open(parts[0], os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
    try:
        for part in parts[1:-1]:
            child = os.open(part, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW,
                            dir_fd=directory)
            os.close(directory)
            directory = child
        descriptor = os.open(parts[-1], os.O_RDONLY | os.O_NONBLOCK | os.O_NOFOLLOW,
                             dir_fd=directory)
        try:
            info = os.fstat(descriptor)
            if info.st_size > limit:
                raise ValueError('input_file_exceeds_bound')
            if not stat.S_ISREG(info.st_mode):
                raise ValueError('unsupported input file')
            return descriptor, info
        except BaseException:
            os.close(descriptor)
            raise
    finally:
        os.close(directory)


def read_regular(path, limit):
    descriptor, before = open_regular(path, limit)
    with os.fdopen(descriptor, 'rb') as source:
        raw = source.read(limit + 1)
        after = os.fstat(source.fileno())
    if (len(raw) > limit or (before.st_size, before.st_mtime_ns, before.st_ctime_ns)
            != (after.st_size, after.st_mtime_ns, after.st_ctime_ns)):
        raise ValueError('input changed or exceeded bound')
    return raw, before

HEX32 = re.compile(r'^[0-9a-f]{32}$')
HEX40 = re.compile(r'^[0-9a-f]{40}$')
HEX64 = re.compile(r'^[0-9a-f]{64}$')
WORKER_RE = re.compile(r'^[a-z][a-z0-9_-]{0,63}$')
TASK_ID_RE = re.compile(r'^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$')
KNOWN_JOB_COLUMNS = (
    'id', 'request_key', 'draft_id', 'draft_sha256', 'worker', 'created_at',
    'state', 'approval_key', 'approved_at', 'reservation_key', 'reserved_at',
    'unknown_at', 'cancelled_at'
)


def fail(message, code=2):
    sys.stderr.write('unio plan: ' + message + '\n')
    raise SystemExit(code)


def is_int(value):
    return type(value) is int


def is_valid_task_id(value):
    return (
        isinstance(value, str)
        and TASK_ID_RE.fullmatch(value) is not None
        and '..' not in value
        and not value.startswith('-')
    )


def is_valid_worker_id(value):
    return isinstance(value, str) and WORKER_RE.fullmatch(value) is not None


def _unique_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError('duplicate JSON key: ' + str(key))
        result[key] = value
    return result


def _reject_constant(name):
    raise ValueError('non-finite JSON constant ' + name)


def _finite(value):
    if isinstance(value, float):
        return math.isfinite(value)
    if isinstance(value, dict):
        return all(_finite(item) for item in value.values())
    if isinstance(value, list):
        return all(_finite(item) for item in value)
    return True


def parse_strict_json(data):
    try:
        obj = json.loads(
            data.decode('utf-8'),
            object_pairs_hook=_unique_object,
            parse_constant=_reject_constant
        )
        if not isinstance(obj, dict) or not _finite(obj):
            return None
    except (ValueError, UnicodeError, RecursionError):
        return None
    return obj


def load_fleet_status():
    sibling = Path(__file__).resolve().parent / 'fleet-status.py'
    if not sibling.is_file():
        fail('fleet-status helper missing from installed library: ' + str(sibling))
    spec = importlib.util.spec_from_file_location('fleet_status', sibling)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


def check_path_no_symlinks(base_dir, relative_path):
    cur = Path(base_dir)
    for part in Path(relative_path).parts:
        cur = cur / part
        if cur.is_symlink():
            return False, 'symlink component detected: ' + part
        try:
            st = cur.lstat()
            if not (stat.S_ISREG(st.st_mode) or stat.S_ISDIR(st.st_mode)):
                return False, 'special file detected: ' + part
        except OSError:
            pass
    return True, None


def resolve_repo(project_root):
    for candidate in (project_root / 'repo', project_root):
        if candidate.is_dir():
            rc, _ = git_query(candidate, ['rev-parse', '--git-dir'], timeout=2.0)
            if rc == 0:
                return candidate
    return None


def git_query(repo_dir, argv, timeout=5.0):
    timeout = remaining(timeout)
    if timeout <= 0:
        return -1, b''
    env = dict(os.environ, GIT_OPTIONAL_LOCKS='0', GIT_NO_REPLACE_OBJECTS='1')
    try:
        proc = subprocess.Popen(
            ['git', '-C', str(repo_dir)] + list(argv),
            stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            env=env,
            start_new_session=True
        )
    except OSError:
        return -1, b''
    deadline = time.monotonic() + timeout
    streams = {proc.stdout.fileno(), proc.stderr.fileno()}
    for descriptor in streams:
        os.set_blocking(descriptor, False)
    output, seen, stopped, failed = bytearray(), 0, False, False
    try:
        while True:
            left = deadline - time.monotonic()
            if left <= 0:
                failed = True
                break
            if not stopped and os.waitid(os.P_PID, proc.pid,
                    os.WEXITED | os.WNOHANG | os.WNOWAIT) is not None:
                try:
                    os.killpg(proc.pid, signal.SIGKILL)
                except ProcessLookupError:
                    pass
                stopped = True
            if not streams:
                if stopped:
                    break
                time.sleep(min(.05, left))
                continue
            for descriptor in select.select(list(streams), [], [], min(.05, left))[0]:
                chunk = os.read(descriptor, min(65536, 65536 - seen + 1))
                if not chunk:
                    streams.remove(descriptor)
                    continue
                seen += len(chunk)
                if seen > 65536:
                    failed = True
                    break
                if descriptor == proc.stdout.fileno():
                    output.extend(chunk)
            if failed:
                break
    except OSError:
        failed = True
    finally:
        try:
            os.killpg(proc.pid, signal.SIGKILL)
        except ProcessLookupError:
            pass
        proc.stdout.close()
        proc.stderr.close()
        proc.wait(timeout=1)
    return (-1, b'') if failed else (proc.returncode, bytes(output))


def get_repo_head(repo_dir, timeout=5.0):
    if repo_dir is None:
        return None
    rc, stdout = git_query(repo_dir, ['rev-parse', '--verify', '-q', 'HEAD^{commit}'], timeout=timeout)
    if rc == 0:
        val = stdout.decode('ascii', 'replace').strip()
        if HEX40.fullmatch(val):
            return val
    return None


def is_ancestor_commit(repo_dir, ancestor, base, timeout=5.0):
    if repo_dir is None:
        return False
    rc, _ = git_query(repo_dir, ['merge-base', '--is-ancestor', ancestor, base], timeout=timeout)
    return rc == 0


def validate_scope_pattern(pattern):
    if not isinstance(pattern, str) or not pattern:
        return False, 'empty scope pattern'
    if '\\' in pattern:
        return False, 'backslash in scope pattern'
    if any(ord(c) < 32 or ord(c) == 127 for c in pattern):
        return False, 'control character in scope pattern'
    if pattern.startswith('/'):
        return False, 'absolute path in scope pattern'
    if pattern == '**':
        return True, None
    parts = pattern.split('/')
    if any(part == '..' for part in parts):
        return False, 'traversal in scope pattern'
    if any(part == '.' for part in parts):
        return False, 'dot component in scope pattern'
    if '' in parts[:-1]:
        return False, 'empty segment or duplicate slash in scope pattern'

    if pattern.endswith('/**'):
        base = pattern[:-3]
        if not base or any(ch in base for ch in ('*', '?', '[', ']')):
            return False, 'invalid recursive glob'
        if os.path.normpath(base) != base:
            return False, 'non-normalized recursive glob'
        return True, None

    if pattern.endswith('/'):
        base = pattern[:-1]
        if not base or any(ch in base for ch in ('*', '?', '[', ']')):
            return False, 'invalid directory scope'
        if os.path.normpath(base) != base:
            return False, 'non-normalized directory scope'
        return True, None

    if any(ch in pattern for ch in ('*', '?', '[', ']')):
        return False, 'unsupported glob pattern'
    if os.path.normpath(pattern) != pattern:
        return False, 'non-normalized path scope'
    return True, None


def scopes_conflict(scope1, scope2):
    if scope1 == '**' or scope2 == '**':
        return True
    if scope1 == scope2:
        return True
    p1 = scope1[:-3] if scope1.endswith('/**') else (scope1[:-1] if scope1.endswith('/') else scope1)
    p2 = scope2[:-3] if scope2.endswith('/**') else (scope2[:-1] if scope2.endswith('/') else scope2)
    is_dir1 = scope1.endswith('/**') or scope1.endswith('/')
    is_dir2 = scope2.endswith('/**') or scope2.endswith('/')

    if p1 == p2:
        return True
    if is_dir1 and p2.startswith(p1 + '/'):
        return True
    if is_dir2 and p1.startswith(p2 + '/'):
        return True
    if p1.startswith(p2 + '/') or p2.startswith(p1 + '/'):
        return True
    return False


def task_scopes_conflict(task_scopes, held_scopes):
    for s1 in task_scopes:
        for s2, held_by in held_scopes:
            if scopes_conflict(s1, s2):
                return True, s1, s2, held_by
    return False, None, None, None


def parse_task_file(coord_dir, task_id, expected_sha256):
    task_file = coord_dir / 'tasks' / (task_id + '.md')
    ok, err = check_path_no_symlinks(coord_dir, Path('tasks') / (task_id + '.md'))
    if not ok:
        return None, None, 'unresolved', 'task_path_unsafe'
    try:
        raw, _ = read_regular(task_file, MAX_TASK_FILE_BYTES)
    except FileNotFoundError:
        return None, None, 'unresolved', 'missing_task_file'
    except (OSError, ValueError):
        return None, None, 'unresolved', 'cannot_read_task_file'

    actual_sha256 = hashlib.sha256(raw).hexdigest()
    if actual_sha256 != expected_sha256:
        return None, None, 'unresolved', 'task_hash_mismatch'

    try:
        text = raw.decode('utf-8')
    except UnicodeDecodeError:
        return None, None, 'unresolved', 'task_file_invalid_utf8'

    lines = text.splitlines()
    scope_headers = [i for i, line in enumerate(lines) if line.strip() == '## Allowed scope']
    if len(scope_headers) != 1:
        return None, None, 'unresolved', 'missing_or_ambiguous_allowed_scope'

    start_idx = scope_headers[0] + 1
    raw_scope_lines = []
    for line in lines[start_idx:]:
        stripped = line.strip()
        if stripped.startswith('#'):
            break
        if stripped.startswith('- '):
            raw_scope_lines.append(stripped[2:].strip())

    if not raw_scope_lines:
        return None, None, 'unresolved', 'empty_allowed_scope'

    validated_scopes = []
    for pat in raw_scope_lines:
        valid, err = validate_scope_pattern(pat)
        if not valid:
            return None, None, 'unresolved', 'unsupported_scope_pattern'
        validated_scopes.append(pat)

    if len(validated_scopes) > 128 or any(len(pat) > 1024 for pat in validated_scopes):
        return None, None, 'unresolved', 'scope_size_exceeded'

    return validated_scopes, actual_sha256, 'ok', None


def observe_browser_job(coord_dir, job_id, worker):
    db_path = coord_dir / 'ui-jobs.sqlite3'
    descriptor, conn = None, None
    deadline = time.monotonic() + remaining(5)
    try:
        if any(os.path.lexists(str(db_path) + suffix)
               for suffix in ('-wal', '-shm', '-journal')):
            return 'unresolved', 'unsupported_queue_sidecar'
        descriptor, before = open_regular(db_path, MAX_DB_BYTES)
        # Keep a no-follow descriptor open throughout SQLite observation. The
        # controlled proc path binds this read-only connection to that inode.
        conn = sqlite3.connect('file:/proc/self/fd/' + str(descriptor)
                               + '?mode=ro&immutable=1', uri=True, timeout=0)
        conn.execute('PRAGMA query_only = ON')
        conn.execute('PRAGMA temp_store = MEMORY')
        conn.set_progress_handler(lambda: int(time.monotonic() >= deadline), 1000)
        installed = Path(__file__).parent / 'browser/job_store.py'
        source = Path(__file__).parent.parent / 'bridge/job_store.py'
        spec = importlib.util.spec_from_file_location('task_plan_job_types',
                                                      installed if installed.is_file() else source)
        types = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(types)
        # These pure validators never construct a store or migrate a database.
        types.JobStore._verify(conn)
        count = conn.execute('SELECT COUNT(*) FROM jobs').fetchone()[0]
        if count > MAX_DB_ROWS:
            return 'unresolved', 'job_database_row_count_exceeded'
        row = conn.execute(types.SELECT_JOB, (job_id,)).fetchone()
        if not row:
            return 'unresolved', 'job_not_found'
        job = types.JobStore._record(row)
        if job['id'] != job_id or job['worker'] != worker:
            return 'unresolved', 'job_worker_mismatch'
        draft_bytes, _ = read_regular(coord_dir / 'ui-plans' / (job['draft_id'] + '.json'),
                                      MAX_DRAFT_FILE_BYTES)
        if hashlib.sha256(draft_bytes).hexdigest() != job['draft_sha256']:
            return 'unresolved', 'draft_hash_mismatch'
        draft = parse_strict_json(draft_bytes)
        if (draft is None or set(draft) != {'schema_version', 'id', 'created_at', 'state', 'request'}
                or type(draft['schema_version']) is not int or draft['schema_version'] != 1
                or draft['id'] != job['draft_id'] or draft['state'] != 'draft'
                or not isinstance(draft['created_at'], str)
                or datetime.datetime.fromisoformat(draft['created_at']).tzinfo is None):
            return 'unresolved', 'malformed_draft_record'
        types.PlanStore._request(draft['request'])
        after = os.fstat(descriptor)
        if ((before.st_size, before.st_mtime_ns, before.st_ctime_ns)
                != (after.st_size, after.st_mtime_ns, after.st_ctime_ns)):
            return 'unresolved', 'queue_changed_during_observation'
        if any(os.path.lexists(str(db_path) + suffix)
               for suffix in ('-wal', '-shm', '-journal')):
            return 'unresolved', 'unsupported_queue_sidecar'
        if time.monotonic() >= deadline:
            return 'unresolved', 'queue_observation_timeout'
        if job['state'] == 'approved':
            return 'eligible', None
        return 'blocked', ('awaiting_owner_approval' if job['state'] == 'awaiting_owner_approval'
                           else 'job_' + job['state'])
    except FileNotFoundError:
        return 'unresolved', 'missing_queue_evidence'
    except (sqlite3.Error, OSError, ValueError, TypeError, UnicodeError, OverflowError, RecursionError):
        return 'unresolved', 'invalid_queue_evidence'
    finally:
        if conn is not None:
            conn.close()
        if descriptor is not None:
            os.close(descriptor)


def detect_cycles(unsatisfied_edges):
    cycle_nodes = set()
    visited = {}

    def dfs(node, path):
        visited[node] = 0
        path.append(node)
        for neighbor in unsatisfied_edges.get(node, []):
            if neighbor in visited:
                if visited[neighbor] == 0:
                    idx = path.index(neighbor)
                    cycle_nodes.update(path[idx:])
            else:
                dfs(neighbor, path)
        path.pop()
        visited[node] = 1

    for node in list(unsatisfied_edges.keys()):
        if node not in visited:
            dfs(node, [])

    if cycle_nodes:
        def reaches_cycle(n, seen):
            if n in cycle_nodes:
                return True
            seen.add(n)
            for neighbor in unsatisfied_edges.get(n, []):
                if neighbor not in seen and reaches_cycle(neighbor, seen):
                    return True
            return False

        for node in list(unsatisfied_edges.keys()):
            if node not in cycle_nodes and reaches_cycle(node, set()):
                cycle_nodes.add(node)

    return cycle_nodes


def validate_inventory(raw_bytes):
    if len(raw_bytes) > MAX_INVENTORY_BYTES:
        fail('inventory file exceeds 256 KiB limit')

    obj = parse_strict_json(raw_bytes)
    if obj is None:
        fail('inventory is not valid strict UTF-8 JSON')

    required_keys = {'schema_version', 'base_revision', 'tasks', 'accepted'}
    if set(obj.keys()) != required_keys:
        fail('inventory root must contain exactly schema_version, base_revision, tasks, and accepted')

    if not is_int(obj['schema_version']) or obj['schema_version'] != 1:
        fail('inventory schema_version must be integer 1')

    if not isinstance(obj['base_revision'], str) or not HEX40.fullmatch(obj['base_revision']):
        fail('inventory base_revision must be full 40-character hex commit')

    if not isinstance(obj['tasks'], list) or len(obj['tasks']) > MAX_TASKS:
        fail('inventory tasks must be a list of at most 128 items')

    if not isinstance(obj['accepted'], list) or len(obj['accepted']) > MAX_ACCEPTED:
        fail('inventory accepted must be a list of at most 128 items')

    accepted_map = {}
    for entry in obj['accepted']:
        if not isinstance(entry, dict) or set(entry.keys()) != {'id', 'task_sha256', 'revision'}:
            fail('accepted entry must contain exactly id, task_sha256, and revision')
        if not is_valid_task_id(entry['id']):
            fail('accepted entry id is invalid')
        if not isinstance(entry['task_sha256'], str) or not HEX64.fullmatch(entry['task_sha256']):
            fail('accepted entry task_sha256 must be 64-hex string')
        if not isinstance(entry['revision'], str) or not HEX40.fullmatch(entry['revision']):
            fail('accepted entry revision must be 40-hex string')
        if entry['id'] in accepted_map:
            fail('duplicate or ambiguous accepted task ID: ' + entry['id'])
        accepted_map[entry['id']] = entry

    seen_tasks = set()
    for task in obj['tasks']:
        if not isinstance(task, dict):
            fail('task item must be a dictionary')
        keys = set(task.keys())
        if keys not in ({'id', 'task_sha256', 'worker', 'depends_on'},
                        {'id', 'task_sha256', 'worker', 'depends_on', 'job_id'}):
            fail('task item has invalid or unknown fields')
        if not is_valid_task_id(task['id']):
            fail('task id is invalid')
        if task['id'] in seen_tasks:
            fail('duplicate task ID in inventory: ' + task['id'])
        seen_tasks.add(task['id'])

        if not isinstance(task['task_sha256'], str) or not HEX64.fullmatch(task['task_sha256']):
            fail('task task_sha256 must be 64-hex string: ' + task['id'])
        if not is_valid_worker_id(task['worker']):
            fail('task worker ID is invalid')
        if not isinstance(task['depends_on'], list) or len(task['depends_on']) > MAX_DEPENDENCIES:
            fail('task depends_on must be a list of at most 128 items: ' + task['id'])

        for dep in task['depends_on']:
            if not isinstance(dep, dict) or set(dep.keys()) != {'id', 'task_sha256', 'revision'}:
                fail('dependency item must contain exactly id, task_sha256, and revision')
            if not is_valid_task_id(dep['id']):
                fail('dependency id is invalid')
            if not isinstance(dep['task_sha256'], str) or not HEX64.fullmatch(dep['task_sha256']):
                fail('dependency task_sha256 must be 64-hex string')
            if not isinstance(dep['revision'], str) or not HEX40.fullmatch(dep['revision']):
                fail('dependency revision must be 40-hex string')

        if 'job_id' in task:
            if not isinstance(task['job_id'], str) or not HEX32.fullmatch(task['job_id']):
                fail('task job_id must be 32-hex string: ' + task['id'])

    return obj, accepted_map


def build_plan(root, inventory, raw_bytes, inv_age_seconds, timeout, runner=sys.executable):
    fleet_mod = load_fleet_status()
    coord_dir = root / 'coord'
    stop_file = coord_dir / 'STOP'
    stop = stop_file.exists()

    repo_dir = resolve_repo(root)
    head_revision = get_repo_head(repo_dir, timeout=min(5.0, timeout))

    observed, statuses = fleet_mod.collect(runner, str(root), remaining(timeout))
    fleet_report = fleet_mod.build_report(str(root), timeout, stop, observed, statuses)

    inv_hash = hashlib.sha256(raw_bytes).hexdigest()
    base_revision = inventory['base_revision']
    base_mismatch = (head_revision is None or head_revision != base_revision)

    verified_accepted = {}
    unverified_accepted = set()
    accepted_map = {entry['id']: entry for entry in inventory['accepted']}

    ancestry = {}
    if not base_mismatch and repo_dir is not None:
        for acc_id, entry in accepted_map.items():
            revision = entry['revision']
            if revision not in ancestry:
                ancestry[revision] = is_ancestor_commit(repo_dir, revision, base_revision)
            if ancestry[revision]:
                verified_accepted[acc_id] = entry
            else:
                unverified_accepted.add(acc_id)
    else:
        unverified_accepted.update(accepted_map.keys())

    tasks = sorted(inventory['tasks'], key=lambda t: t['id'])
    policy = observed.get('policy')
    agents_obs = observed.get('agents')
    readiness_obs = observed.get('readiness')

    # Step 1: Pre-process each task individually
    pre_results = {}
    for task in tasks:
        tid = task['id']
        worker = task['worker']
        agent = worker.split('-')[0]
        group = policy['accounts'].get(agent, agent) if policy else agent
        res = {
            'id': tid,
            'status': None,
            'worker': worker,
            'agent': agent,
            'group': group,
            'reasons': [],
            'explanation': None,
            'scopes': [],
            'dependencies': [],
            'job_id': task.get('job_id'),
            'dispatch_readiness': 'unknown',
            '_scope_valid': False,
        }

        if base_mismatch:
            res['status'] = 'unresolved'
            res['reasons'].append('base_revision_mismatch')
            res['explanation'] = (
                f"workspace repo HEAD ({head_revision[:12] if head_revision else 'unknown'}) "
                f"does not match inventory base_revision ({base_revision[:12]})"
            )
            pre_results[tid] = res
            continue

        # Check if already integrated at base
        if tid in accepted_map:
            acc = accepted_map[tid]
            if acc['task_sha256'] == task['task_sha256'] and tid in verified_accepted:
                res['status'] = 'blocked'
                res['reasons'].append('already_integrated')
                res['explanation'] = f"task hash already integrated at base revision {acc['revision'][:12]}"
                pre_results[tid] = res
                continue

        # Parse task file and scope
        scopes, _, parse_st, parse_reason = parse_task_file(coord_dir, tid, task['task_sha256'])
        if parse_st != 'ok':
            res['status'] = 'unresolved'
            res['reasons'].append(parse_reason)
            res['explanation'] = f"task markdown or scope invalid: {parse_reason}"
            pre_results[tid] = res
            continue

        res['scopes'] = scopes
        res['_scope_valid'] = True

        # Check optional browser job
        if task.get('job_id'):
            job_st, job_reason = observe_browser_job(coord_dir, task['job_id'], worker)
            if job_st == 'unresolved':
                res['status'] = 'unresolved'
                res['reasons'].append(job_reason)
                res['explanation'] = f"browser queue observation unresolved: {job_reason}"
                pre_results[tid] = res
                continue
            elif job_st == 'blocked':
                res['status'] = 'blocked'
                res['reasons'].append(job_reason)
                res['explanation'] = f"browser queue job blocked: {job_reason}"
                pre_results[tid] = res
                continue

        # Check dependencies
        dep_blocked_reasons = []
        dep_unresolved_reasons = []
        for dep in task['depends_on']:
            dep_id = dep['id']
            if dep_id not in accepted_map or dep_id in unverified_accepted:
                dep_unresolved_reasons.append(f"missing_acceptance_evidence:{dep_id}")
            else:
                acc = accepted_map[dep_id]
                if dep['task_sha256'] != acc['task_sha256']:
                    dep_blocked_reasons.append(
                        f"dependency_{dep_id}_hash_mismatch: required {dep['task_sha256'][:12]} != accepted {acc['task_sha256'][:12]}"
                    )
                elif dep['revision'] != acc['revision']:
                    dep_blocked_reasons.append(
                        f"dependency_{dep_id}_revision_mismatch: required {dep['revision'][:12]} != accepted {acc['revision'][:12]}"
                    )
                else:
                    res['dependencies'].append({
                        'id': dep_id,
                        'revision': acc['revision'],
                        'task_sha256': acc['task_sha256']
                    })

        if dep_blocked_reasons:
            res['status'] = 'blocked'
            res['reasons'].extend(dep_blocked_reasons)
            res['explanation'] = '; '.join(dep_blocked_reasons)
            pre_results[tid] = res
            continue
        elif dep_unresolved_reasons:
            res['status'] = 'unresolved'
            res['reasons'].extend(dep_unresolved_reasons)
            res['explanation'] = '; '.join(dep_unresolved_reasons)
            pre_results[tid] = res
            continue

        pre_results[tid] = res

    # Step 2: Cycle detection among unsatisfied inventory dependencies
    if not base_mismatch:
        unsatisfied_edges = {}
        inventory_tids = {t['id'] for t in tasks}
        for task in tasks:
            tid = task['id']
            for dep in task['depends_on']:
                dep_id = dep['id']
                if dep_id in inventory_tids and dep_id not in verified_accepted:
                    unsatisfied_edges.setdefault(tid, set()).add(dep_id)

        cycle_nodes = detect_cycles(unsatisfied_edges)
        for tid in cycle_nodes:
            res = pre_results[tid]
            res['status'] = 'unresolved'
            if 'dependency_cycle' not in res['reasons']:
                res['reasons'].append('dependency_cycle')
            res['explanation'] = 'dependency cycle detected among unsatisfied inventory tasks'

    # Step 3: Check for unknown/ambiguous scope on any unfinished task
    if not base_mismatch:
        bad_scope_tasks = []
        for task in tasks:
            tid = task['id']
            res = pre_results[tid]
            if res['status'] == 'blocked' and 'already_integrated' in res['reasons']:
                continue
            if not res['_scope_valid']:
                bad_scope_tasks.append(tid)

        if bad_scope_tasks:
            for task in tasks:
                tid = task['id']
                res = pre_results[tid]
                if res['status'] is None:
                    res['status'] = 'unresolved'
                    res['reasons'].append('disjointness_unknown')
                    res['explanation'] = (
                        f"disjointness cannot be established; unfinished task '{bad_scope_tasks[0]}' "
                        f"has unknown/ambiguous scope"
                    )

    # Step 4: Fleet admission checks for remaining candidate tasks
    if not base_mismatch:
        for task in tasks:
            tid = task['id']
            res = pre_results[tid]
            if res['status'] is not None:
                continue

            if stop:
                res['status'] = 'blocked'
                res['reasons'].append('project_STOP')
                res['explanation'] = 'project STOP is set'
                continue

            if statuses.get('policy') != 'ok':
                res['status'] = 'unresolved'
                res['reasons'].append('policy_unavailable')
                res['explanation'] = 'policy unavailable, account limits unknown'
                continue

            agent_info = None
            if agents_obs:
                agent_info = agents_obs.get(res['agent'])
            if agent_info is None:
                res['status'] = 'unresolved'
                res['reasons'].append('agent_unknown')
                res['explanation'] = f"agent '{res['agent']}' not listed in configured agents"
                continue

            if agent_info.get('bench_off'):
                res['status'] = 'blocked'
                res['reasons'].append('agent_off')
                res['explanation'] = f"agent '{res['agent']}' is off"
                continue

            if agent_info.get('binary_present') is False:
                res['status'] = 'blocked'
                res['reasons'].append('binary_missing')
                res['explanation'] = f"agent '{res['agent']}' binary not installed"
                continue
            elif agent_info.get('binary_present') is None:
                res['status'] = 'unresolved'
                res['reasons'].append('binary_unknown')
                res['explanation'] = f"agent '{res['agent']}' binary presence unknown"
                continue

            # Fresh auth check
            if readiness_obs:
                agent_auth = readiness_obs.get(res['agent'])
                if agent_auth and agent_auth.get('status') == 'fresh' and agent_auth.get('authentication') == 'signed_out':
                    res['status'] = 'blocked'
                    res['reasons'].append('auth_signed_out')
                    res['explanation'] = f"agent '{res['agent']}' authentication is fresh signed_out"
                    continue

            # Fresh zero allowance check
            grp_data = fleet_report['groups'].get(res['group'])
            zero_allowance = False
            if grp_data:
                manual = grp_data.get('manual_allowance')
                if manual and manual.get('status') == 'recorded':
                    for win in manual.get('windows', {}).values():
                        if win.get('status') == 'fresh' and win.get('usable_remaining_percent') == 0:
                            zero_allowance = True
                            break
                cached = grp_data.get('cached_allowance')
                if cached and cached.get('freshness') == 'fresh' and cached.get('state') == 'ok':
                    for bkt in cached.get('buckets', {}).values():
                        for win in bkt.get('windows', {}).values():
                            if win and win.get('status') == 'fresh' and win.get('usable_remaining_percent') == 0:
                                zero_allowance = True
                                break
            if zero_allowance:
                res['status'] = 'blocked'
                res['reasons'].append('zero_allowance')
                res['explanation'] = f"shared budget group '{res['group']}' has fresh zero allowance"
                continue

    # Step 5: Busy groups and inferred active scope
    warnings = []
    occupied_scopes = []  # list of tuples: (scope_pattern, holding_task_or_reason)
    virtual_occupied = {}

    if not base_mismatch:
        busy_groups = {}
        if policy and isinstance(policy.get('active_with_lead'), dict):
            for g_name, occ in policy['active_with_lead'].items():
                if is_int(occ) and occ > 0:
                    busy_groups[g_name] = occ
        for g_name, g_view in fleet_report['groups'].items():
            occ = g_view.get('occupied') or 0
            if occ > 0:
                busy_groups[g_name] = max(busy_groups.get(g_name, 0), occ)
            virtual_occupied[g_name] = occ

        for g_name, occ in busy_groups.items():
            virtual_occupied[g_name] = occ
            # Find unfinished tasks in inventory for this group
            group_tasks = [
                t for t in tasks
                if pre_results[t['id']]['group'] == g_name
                and not (pre_results[t['id']]['status'] == 'blocked'
                         and 'already_integrated' in pre_results[t['id']]['reasons'])
                and pre_results[t['id']]['_scope_valid']
            ]
            if group_tasks:
                for gt in group_tasks:
                    for sc in pre_results[gt['id']]['scopes']:
                        occupied_scopes.append((sc, f"inferred busy task '{gt['id']}' in group '{g_name}'"))
            else:
                warnings.append(
                    f"group '{g_name}' is busy ({occ} occupied) with no task in inventory; active write scope unknown"
                )

    # Step 6: Greedy selection in stable sorted task ID order
    if not base_mismatch:
        for task in tasks:
            tid = task['id']
            res = pre_results[tid]
            if res['status'] is not None:
                continue

            grp = res['group']
            limit = fleet_report['groups'].get(grp, {}).get('limit')
            cur_occ = virtual_occupied.get(grp, 0)

            if limit is not None and cur_occ >= limit:
                res['status'] = 'blocked'
                res['reasons'].append('group_full')
                res['explanation'] = f"shared budget group '{grp}' is full (limit {limit})"
                continue

            conflict, s1, s2, held_by = task_scopes_conflict(res['scopes'], occupied_scopes)
            if conflict:
                res['status'] = 'blocked'
                res['reasons'].append('scope_conflict')
                res['explanation'] = f"write scope '{s1}' conflicts with '{s2}' held by {held_by}"
                continue

            # Task is selected!
            res['status'] = 'ready'
            res['reasons'] = []
            res['explanation'] = (
                "recommended; all local checks clear; provider availability remains unknown "
                "and admission must be rechecked at launch"
            )
            virtual_occupied[grp] = cur_occ + 1
            for sc in res['scopes']:
                occupied_scopes.append((sc, f"task '{tid}'"))

    # Final pass: clean up internal keys
    final_tasks = []
    ready_count = 0
    blocked_count = 0
    unresolved_count = 0

    for task in tasks:
        tid = task['id']
        res = pre_results[tid]
        res.pop('_scope_valid', None)
        if stop:
            res['status'] = 'blocked'
            if 'project_STOP' not in res['reasons']:
                res['reasons'].append('project_STOP')
            res['explanation'] = 'project STOP is set; ' + (res['explanation'] or 'launch is blocked')
        if res['status'] == 'ready':
            ready_count += 1
        elif res['status'] == 'blocked':
            blocked_count += 1
        else:
            res['status'] = 'unresolved'
            unresolved_count += 1
        final_tasks.append(res)

    report = {
        'schema_version': SCHEMA_VERSION,
        'project': str(root.resolve()),
        'checked_at': datetime.datetime.now(datetime.timezone.utc).isoformat(),
        'timeout_seconds': timeout,
        'base_revision': base_revision,
        'head_revision': head_revision,
        'inventory_hash': inv_hash,
        'inventory_file_age_seconds': round(inv_age_seconds, 2),
        'fleet_age_seconds': round(max(0.0, (datetime.datetime.now(datetime.timezone.utc)
            - datetime.datetime.fromisoformat(fleet_report['checked_at'])).total_seconds()), 3),
        'fleet_sources': statuses,
        'stop': stop,
        'summary': {
            'total': len(final_tasks),
            'ready': ready_count,
            'blocked': blocked_count,
            'unresolved': unresolved_count
        },
        'warnings': warnings,
        'tasks': final_tasks
    }
    return report


def render_text(report):
    lines = []
    lines.append('Project: ' + report['project'].encode('unicode_escape').decode('ascii'))
    lines.append(f"Base revision: {report['base_revision'][:12]} | Repo HEAD: {report['head_revision'][:12] if report['head_revision'] else 'unknown'}")
    lines.append(f"Inventory age: {report['inventory_file_age_seconds']}s | Hash: {report['inventory_hash'][:12]}")
    if report['stop']:
        lines.append('STOP: active (all tasks blocked)')
    lines.append(
        f"Summary: total {report['summary']['total']} | "
        f"ready {report['summary']['ready']} | "
        f"blocked {report['summary']['blocked']} | "
        f"unresolved {report['summary']['unresolved']}"
    )

    if report['warnings']:
        lines.append('')
        lines.append('Warnings:')
        for w in report['warnings']:
            lines.append('  ! ' + w)

    lines.append('')
    for t in report['tasks']:
        st = t['status'].upper()
        line = f"[{st}] {t['id']} (worker: {t['worker']}, group: {t['group']})"
        lines.append(line)
        if t['reasons']:
            lines.append('  reasons: ' + ', '.join(t['reasons']))
        if t['explanation']:
            lines.append('  detail: ' + t['explanation'])
        if t['scopes']:
            lines.append('  scopes: ' + ', '.join(t['scopes']))
        if t['dependencies']:
            deps_str = ', '.join(f"{d['id']}@{d['revision'][:8]}" for d in t['dependencies'])
            lines.append('  dependencies satisfied: ' + deps_str)
        if t['job_id']:
            lines.append('  job_id: ' + t['job_id'])
        lines.append('')

    lines.append('Recommendation only; not launch authority. Provider availability remains unknown.')
    return '\n'.join(lines)


def main(argv=None):
    global OBSERVATION_DEADLINE
    parser = argparse.ArgumentParser(
        prog='unio plan', allow_abbrev=False,
        description='Local read-only concurrent recommendations before dispatch: '
                    'inventory tasks, dependencies, write scopes, and shared budget groups.')
    parser.add_argument('--inventory', metavar='PATH',
                        help='path to schema-1 task inventory JSON file')
    parser.add_argument('--project', metavar='PATH',
                        help='explicit physical project root (coord/ and wt/)')
    parser.add_argument('--json', action='store_true',
                        help='write exactly one schema-1 JSON object')
    parser.add_argument('--timeout', type=int, metavar='SECONDS', default=10,
                        help='whole observation deadline, 1..60 seconds (default 10)')

    native = list(sys.argv[1:] if argv is None else argv)
    if not native:
        fail('arguments missing; pass --help for usage')
    # If the dispatcher passes runner as first argument
    if native[0].startswith('-'):
        fail('installed runner path missing')
    runner = native.pop(0)
    args = parser.parse_args(native)

    if not 1 <= args.timeout <= 60:
        fail('--timeout must be 1..60 seconds')
    if not args.inventory:
        fail('--inventory PATH is required')
    if not args.project:
        fail('no project selected; pass --project PATH')

    OBSERVATION_DEADLINE = time.monotonic() + args.timeout
    inv_path = Path(args.inventory)
    try:
        raw_bytes, st = read_regular(inv_path, MAX_INVENTORY_BYTES)
    except FileNotFoundError:
        fail('inventory file does not exist')
    except ValueError as error:
        if str(error) == 'input_file_exceeds_bound':
            fail('inventory file exceeds 256 KiB limit')
        fail('inventory file must be regular and bounded')
    except OSError:
        fail('inventory file must not be a symlink or have symlink components; it must be readable')

    inv_age = max(0.0, time.time() - st.st_mtime)
    inventory, _ = validate_inventory(raw_bytes)

    root = Path(os.path.realpath(os.path.abspath(args.project)))
    for req in ('coord', 'wt'):
        if (root / req).is_symlink() or not (root / req).is_dir():
            fail('project requires physical coord/ and wt/ directories')

    plan_report = build_plan(root, inventory, raw_bytes, inv_age, args.timeout, runner=runner)

    if args.json:
        sys.stdout.write(json.dumps(plan_report, indent=2, ensure_ascii=True, allow_nan=False) + '\n')
    else:
        sys.stdout.write(render_text(plan_report) + '\n')
    return 0


if __name__ == '__main__':
    def interrupted(_signal, _frame):
        raise KeyboardInterrupt
    signal.signal(signal.SIGTERM, interrupted)
    try:
        sys.exit(main())
    except KeyboardInterrupt:
        sys.stderr.write('unio plan: interrupted\n')
        raise SystemExit(130)
UNIO_TASK_PLAN_PY
# END EMBEDDED TASK PLAN
# BEGIN EMBEDDED TASK DISPATCH
# Check every generated destination before replacing any task dispatch file.
for dispatch_dir in "$CONF_DIR/lib"; do
  if [ -L "$dispatch_dir" ] || { [ -e "$dispatch_dir" ] && [ ! -d "$dispatch_dir" ]; }; then
    echo "unio: refusing unsafe task dispatch directory: $dispatch_dir" >&2
    exit 1
  fi
done
for dispatch_name in task-dispatch.py; do
  dispatch_file="$CONF_DIR/lib/$dispatch_name"
  if [ -L "$dispatch_file" ] || { [ -e "$dispatch_file" ] && { [ ! -f "$dispatch_file" ] || [ "$(stat -c '%h' -- "$dispatch_file")" != 1 ]; }; }; then
    echo "unio: refusing unsafe task dispatch file: $dispatch_file" >&2
    exit 1
  fi
done
mkdir -p "$CONF_DIR/lib"
cat > "$CONF_DIR/lib/task-dispatch.py" <<'UNIO_TASK_DISPATCH_PY'
#!/usr/bin/env python3
# Unio — Copyright (C) 2026 Daniel Mitev
# SPDX-License-Identifier: AGPL-3.0-only; additional terms in NOTICE.
"""Explicit owner-granted dispatch over the existing execution service.

Prepare, approve and start each delegate to one ExecutionService call. A fresh
start first rebuilds the checked task plan inside the service lock; replays
return existing evidence. No scheduler, retry, automatic approval, review,
acceptance or merge. Launcher acceptance is not task success.
"""

import argparse
import contextlib
import hashlib
import importlib.util
import io
import json
import os
import re
import signal
import sys
import time
from pathlib import Path

SCHEMA_VERSION = 1
MAX_GRANT_BYTES = 16 * 1024
MAX_PATH_CHARS = 4096
MAX_REASONS = 16
MAX_REASON_CHARS = 160
GRANT_FIELDS = ('schema_version', 'project', 'engine', 'config_dir', 'template_path',
                'worker', 'reviewer', 'worker_lab', 'reviewer_lab')
HEX32 = re.compile(r'[0-9a-f]{32}')
HEX64 = re.compile(r'[0-9a-f]{64}')
LABEL = re.compile(r'[a-z][a-z0-9_-]{0,63}')
# Codes whose effect on durable state cannot be ruled out.
UNKNOWN_CODES = frozenset(('outcome_unknown', 'storage_unavailable'))
EXIT_OK, EXIT_REFUSED, EXIT_UNKNOWN = 0, 1, 3


def fail(message, code=2):
    sys.stderr.write('unio dispatch: ' + message + '\n')
    raise SystemExit(code)


def load_module(name, path):
    if not path.is_file():
        fail('helper missing from installed library: ' + str(path))
    spec = importlib.util.spec_from_file_location(name, path)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def load_planner():
    return load_module('task_plan', Path(__file__).resolve().parent / 'task-plan.py')


def load_service():
    here = Path(__file__).resolve().parent
    installed = here / 'browser/execution_service.py'
    source = here.parent / 'bridge/execution_service.py'
    return load_module('execution_service', installed if installed.is_file() else source)


def physical_path(grant, key, directory):
    value = grant[key]
    if (not isinstance(value, str) or not value or len(value) > MAX_PATH_CHARS
            or any(ord(char) < 32 or ord(char) == 127 for char in value)
            or not os.path.isabs(value) or os.path.normpath(value) != value
            or os.path.realpath(value) != value):
        fail('grant ' + key + ' must be an absolute physical path')
    if directory and not os.path.isdir(value):
        fail('grant ' + key + ' must be an existing directory')
    if not directory and not os.path.isfile(value):
        fail('grant ' + key + ' must be an existing regular file')
    return value


def read_grant(path, planner):
    try:
        raw, _ = planner.read_regular(Path(path), MAX_GRANT_BYTES)
    except FileNotFoundError:
        fail('grant file does not exist')
    except ValueError as error:
        if str(error) == 'input_file_exceeds_bound':
            fail('grant file exceeds 16 KiB limit')
        fail('grant file must be regular and bounded')
    except OSError:
        fail('grant file must not be a symlink or have symlink components; it must be readable')
    grant = planner.parse_strict_json(raw)
    if grant is None:
        fail('grant is not a strict UTF-8 JSON object')
    if set(grant) != set(GRANT_FIELDS):
        fail('grant must contain exactly ' + ', '.join(GRANT_FIELDS))
    if type(grant['schema_version']) is not int or grant['schema_version'] != 1:
        fail('grant schema_version must be integer 1')
    for key in ('project', 'config_dir'):
        physical_path(grant, key, True)
    for key in ('engine', 'template_path'):
        physical_path(grant, key, False)
    if not os.access(grant['engine'], os.X_OK):
        fail('grant engine must be executable')
    for key in ('worker', 'reviewer'):
        if not isinstance(grant[key], str) or LABEL.fullmatch(grant[key]) is None:
            fail('grant ' + key + ' must be a lowercase worker label')
    for key in ('worker_lab', 'reviewer_lab'):
        value = grant[key]
        if (not isinstance(value, str) or not value.strip() or len(value) > 100
                or any(ord(char) < 32 or ord(char) == 127 for char in value)):
            fail('grant ' + key + ' must be a printable label of at most 100 characters')
    if grant['worker_lab'] == grant['reviewer_lab']:
        fail('grant worker_lab and reviewer_lab must differ')
    root = Path(grant['project'])
    for required in ('coord', 'wt'):
        if (root / required).is_symlink() or not (root / required).is_dir():
            fail('granted project requires physical coord/ and wt/ directories')
    return grant


def read_inventory(planner, path, expected):
    """Bounded no-follow read, exact hash, then the planner's schema-1 checks."""
    try:
        raw, info = planner.read_regular(Path(path), planner.MAX_INVENTORY_BYTES)
    except (OSError, ValueError):
        return None, 'inventory_unreadable'
    if hashlib.sha256(raw).hexdigest() != expected:
        return None, 'inventory_hash_mismatch'
    diagnostics = io.StringIO()
    try:
        with contextlib.redirect_stderr(diagnostics):
            inventory, _ = planner.validate_inventory(raw)
    except SystemExit:
        return None, 'inventory_invalid'
    return (inventory, raw, max(0.0, time.time() - info.st_mtime)), None


def bounded_reasons(reasons):
    result = []
    for reason in list(reasons)[:MAX_REASONS]:
        text = str(reason).encode('ascii', 'backslashreplace').decode('ascii')
        result.append(text[:MAX_REASON_CHARS])
    return result


class Preflight:
    """Fresh-start check; the service calls it once inside its coordination lock."""

    def __init__(self, service_module, planner, grant, runner, inventory_path, inventory_sha256, timeout):
        self.error = service_module.ExecutionError
        self.planner, self.grant, self.runner = planner, grant, runner
        self.inventory_path, self.inventory_sha256 = inventory_path, inventory_sha256
        self.timeout = timeout
        self.state = 'not_run'
        self.reason = None
        self.plan = None

    def __call__(self, binding):
        self.state = 'running'
        try:
            code, reason = self.check(binding)
        except Exception:  # noqa: BLE001 - every unexpected planner failure refuses
            code, reason = 'not_ready', 'plan_unavailable'
        except SystemExit:
            code, reason = 'not_ready', 'plan_unavailable'
        if reason is not None:
            self.state, self.reason = 'refused', reason
            raise self.error(code)
        self.state = 'passed'

    def check(self, binding):
        planner = self.planner
        planner.OBSERVATION_DEADLINE = time.monotonic() + self.timeout
        loaded, reason = read_inventory(planner, self.inventory_path, self.inventory_sha256)
        if reason:
            return 'conflict', reason
        inventory, raw, age = loaded
        job_id, preview = binding['job_id'], binding['preview']
        task_id = preview['task_id']
        rows = [row for row in inventory['tasks']
                if row['id'] == task_id or row.get('job_id') == job_id]
        if not rows:
            return 'conflict', 'inventory_row_missing'
        if len(rows) != 1:
            return 'conflict', 'inventory_row_ambiguous'
        row = rows[0]
        if (row['id'] != task_id or row.get('job_id') != job_id
                or row['worker'] != self.grant['worker'] or preview['worker'] != self.grant['worker']
                or row['task_sha256'] != preview['task_sha256']):
            return 'conflict', 'inventory_binding_mismatch'
        if inventory['base_revision'] != binding['base_revision']:
            return 'conflict', 'inventory_base_mismatch'
        report = planner.build_plan(Path(self.grant['project']), inventory, raw, age,
                                    self.timeout, runner=self.runner)
        selected = [task for task in report['tasks']
                    if task['id'] == task_id or task['job_id'] == job_id]
        if (len(selected) != 1 or selected[0]['id'] != task_id or selected[0]['job_id'] != job_id
                or selected[0]['worker'] != self.grant['worker']
                or report['inventory_hash'] != self.inventory_sha256
                or report['base_revision'] != binding['base_revision']):
            return 'conflict', 'plan_binding_mismatch'
        task = selected[0]
        self.plan = dict(status=task['status'], reasons=bounded_reasons(task['reasons']),
                         stop=bool(report['stop']), head_matches_base=(
                             report['head_revision'] == binding['base_revision']))
        if task['status'] != 'ready' or report['head_revision'] != binding['base_revision']:
            return 'not_ready', 'plan_' + task['status']
        return None, None


def summarize(view):
    job, preview = view['job'], view['preview']
    return dict(
        job=dict(id=job['id'], state=job['state'], worker=job['worker'],
                 draft_sha256=job['draft_sha256']),
        task=dict(id=preview['task_id'], sha256=preview['task_sha256']),
        preview_sha256=preview['preview_hash'],
        execution=dict(state=view['execution']['state'],
                       launcher_exit=view['execution']['launcher_exit']),
        warnings=bounded_reasons(view['warnings']))


def view_outcome(operation, view):
    warnings = view['warnings']
    if 'outcome_unknown' in warnings:
        return 'unknown'
    if operation == 'prepare':
        return 'prepared'
    if operation == 'approve':
        return 'approved' if view['job']['state'] == 'approved' else 'unknown'
    execution = view['execution']['state']
    if execution == 'launch_accepted':
        return 'launch_accepted'
    if execution == 'launch_failed':
        return 'launch_failed'
    return 'unknown'


def error_outcome(operation, code, preflight):
    if code in UNKNOWN_CODES:
        return 'unknown'
    if operation == 'start' and preflight is not None and preflight.state == 'passed':
        # After a passed preflight the service may already have reserved or launched.
        return 'launch_failed' if code == 'native_unavailable' else 'unknown'
    return 'refused'


def render_text(report):
    lines = ['Dispatch ' + report['operation'] + ': ' + report['outcome']]
    if report['error']:
        lines.append('Error: ' + report['error'] + (' (' + report['reason'] + ')' if report['reason'] else ''))
    if report['job']:
        job = report['job']
        lines.append('Job: {} (state {}, worker {})'.format(job['id'], job['state'], job['worker']))
        lines.append('Draft sha256: ' + job['draft_sha256'])
        lines.append('Task: {} sha256 {}'.format(report['task']['id'], report['task']['sha256']))
        lines.append('Preview sha256: ' + report['preview_sha256'])
        execution = report['execution']
        exit_text = '' if execution['launcher_exit'] is None else ' (launcher exit {})'.format(
            execution['launcher_exit'])
        lines.append('Execution: ' + execution['state'] + exit_text)
    if report['replay'] is not None:
        lines.append('Replay: ' + ('yes, existing evidence; no new launch' if report['replay'] else 'no'))
    if report['plan']:
        plan = report['plan']
        lines.append('Plan: ' + plan['status'] + (' (' + ', '.join(plan['reasons']) + ')'
                                                    if plan['reasons'] else ''))
    if report['warnings']:
        lines.append('Warnings: ' + ', '.join(report['warnings']))
    if report['operation'] == 'prepare' and report['outcome'] == 'prepared':
        lines.append('Inspect coord/ui-execution/bindings/' + report['job']['id']
                     + '.md before an explicit approve.')
    lines.append('Launcher acceptance is not task success, review or integration.')
    return '\n'.join(lines)


def build_parser():
    parser = argparse.ArgumentParser(
        prog='unio dispatch', allow_abbrev=False,
        description='Explicit owner-granted dispatch: prepare, approve, or start one job '
                    'through the existing execution service. No scheduler or retries.')
    parser.add_argument('--grant', metavar='PATH', required=True,
                        help='physical schema-1 owner grant JSON (at most 16 KiB)')
    parser.add_argument('--project', metavar='PATH',
                        help='optional project root; must equal the granted project')
    parser.add_argument('--json', action='store_true',
                        help='write exactly one schema-1 JSON object')
    operations = parser.add_subparsers(dest='operation', metavar='OPERATION', required=True)
    prepare = operations.add_parser('prepare', allow_abbrev=False,
                                    help='bind a saved draft to a job (no provider call)')
    prepare.add_argument('--draft-id', required=True, metavar='ID')
    prepare.add_argument('--draft-sha256', required=True, metavar='HASH')
    prepare.add_argument('--request-key', required=True, metavar='KEY')
    approve = operations.add_parser('approve', allow_abbrev=False,
                                    help='record explicit owner approval (no provider call)')
    approve.add_argument('--job-id', required=True, metavar='ID')
    approve.add_argument('--draft-sha256', required=True, metavar='HASH')
    approve.add_argument('--preview-sha256', required=True, metavar='HASH')
    approve.add_argument('--approval-key', required=True, metavar='KEY')
    start = operations.add_parser('start', allow_abbrev=False,
                                  help='one explicit native launch after a fresh ready plan')
    start.add_argument('--job-id', required=True, metavar='ID')
    start.add_argument('--approval-key', required=True, metavar='KEY')
    start.add_argument('--reservation-key', required=True, metavar='KEY')
    start.add_argument('--inventory', required=True, metavar='PATH',
                       help='schema-1 task inventory naming ui-JOB_ID with its job_id')
    start.add_argument('--inventory-sha256', required=True, metavar='HASH')
    start.add_argument('--timeout', type=int, default=10, metavar='SECONDS',
                       help='plan observation deadline, 1..60 seconds (default 10)')
    return parser


def validate_arguments(args):
    for name in ('draft_id', 'job_id', 'request_key', 'approval_key', 'reservation_key'):
        value = getattr(args, name, None)
        if value is not None and HEX32.fullmatch(value) is None:
            fail('--' + name.replace('_', '-') + ' must be 32 lowercase hex characters')
    for name in ('draft_sha256', 'preview_sha256', 'inventory_sha256'):
        value = getattr(args, name, None)
        if value is not None and HEX64.fullmatch(value) is None:
            fail('--' + name.replace('_', '-') + ' must be a 64-character lowercase SHA-256')
    if args.operation == 'start':
        if not 1 <= args.timeout <= 60:
            fail('--timeout must be 1..60 seconds')
        if not args.inventory:
            fail('--inventory PATH is required')


def main(argv=None):
    native = list(sys.argv[1:] if argv is None else argv)
    parser = build_parser()
    if native[:1] in (['-h'], ['--help']):
        parser.print_help()
        return 0
    if not native:
        fail('arguments missing; pass --help for usage')
    if native[0].startswith('-'):
        fail('installed runner path missing')
    runner = native.pop(0)
    args = parser.parse_args(native)
    validate_arguments(args)

    planner = load_planner()
    grant = read_grant(args.grant, planner)
    if os.path.realpath(os.path.abspath(runner)) != grant['engine']:
        fail('grant engine does not match the invoked Unio executable')
    if args.project is not None and os.path.realpath(os.path.abspath(args.project)) != grant['project']:
        fail('--project does not match the granted project')
    configured = os.environ.get('UNIO_CONF_DIR')
    if configured is not None and os.path.realpath(os.path.abspath(configured)) != grant['config_dir']:
        fail('UNIO_CONF_DIR does not match the granted config_dir')
    # The planner's fleet observation must read the same configuration as the launch.
    os.environ['UNIO_CONF_DIR'] = grant['config_dir']
    if args.operation == 'start':
        _, reason = read_inventory(planner, args.inventory, args.inventory_sha256)
        if reason:
            fail('start refused before the service: ' + reason, EXIT_REFUSED)

    module = load_service()
    report = dict(schema_version=SCHEMA_VERSION, operation=args.operation, outcome='refused',
                  error=None, reason=None, replay=None, job=None, task=None, preview_sha256=None,
                  execution=None, warnings=[], plan=None)
    preflight = None
    try:
        service = module.ExecutionService(
            grant['project'], grant['engine'], grant['worker'], grant['reviewer'],
            grant['config_dir'], grant['template_path'], grant['worker_lab'], grant['reviewer_lab'])
    except module.ExecutionError as error:
        report.update(error=error.code, reason='service_unavailable')
    else:
        try:
            if args.operation == 'prepare':
                view = service.prepare(args.draft_id, args.draft_sha256, args.request_key)
            elif args.operation == 'approve':
                view = service.approve(args.job_id, args.draft_sha256, args.approval_key,
                                       args.preview_sha256)
            else:
                preflight = Preflight(module, planner, grant, grant['engine'], args.inventory,
                                      args.inventory_sha256, args.timeout)
                view = service.start(args.job_id, args.approval_key, args.reservation_key,
                                     preflight=preflight)
            report.update(summarize(view))
            report['outcome'] = view_outcome(args.operation, view)
        except module.ExecutionError as error:
            report.update(error=error.code,
                          outcome=error_outcome(args.operation, error.code, preflight))
            if preflight is not None and preflight.state == 'refused':
                report['reason'] = preflight.reason
        finally:
            service.close()
    if preflight is not None:
        report['replay'] = preflight.state == 'not_run' and report['error'] is None
        report['plan'] = preflight.plan
    if args.json:
        sys.stdout.write(json.dumps(report, indent=2, ensure_ascii=True, allow_nan=False) + '\n')
    else:
        sys.stdout.write(render_text(report) + '\n')
    if report['outcome'] in ('prepared', 'approved', 'launch_accepted'):
        return EXIT_OK
    return EXIT_UNKNOWN if report['outcome'] == 'unknown' else EXIT_REFUSED


if __name__ == '__main__':
    def interrupted(_signal, _frame):
        raise KeyboardInterrupt
    signal.signal(signal.SIGTERM, interrupted)
    try:
        sys.exit(main())
    except KeyboardInterrupt:
        sys.stderr.write('unio dispatch: interrupted; any started outcome stays unknown\n')
        raise SystemExit(130)
UNIO_TASK_DISPATCH_PY
# END EMBEDDED TASK DISPATCH
# BEGIN EMBEDDED DASHBOARD
# Check the generated destination before replacing the dashboard helper.
if [ -L "$CONF_DIR/lib" ] || { [ -e "$CONF_DIR/lib" ] && [ ! -d "$CONF_DIR/lib" ]; }; then
  echo "unio: refusing unsafe dashboard directory: $CONF_DIR/lib" >&2
  exit 1
fi
dashboard_file="$CONF_DIR/lib/dashboard.py"
if [ -L "$dashboard_file" ] || { [ -e "$dashboard_file" ] && { [ ! -f "$dashboard_file" ] || [ "$(stat -c '%h' -- "$dashboard_file")" != 1 ]; }; }; then
  echo "unio: refusing unsafe dashboard file: $dashboard_file" >&2
  exit 1
fi
mkdir -p "$CONF_DIR/lib"
cat > "$dashboard_file" <<'UNIO_DASHBOARD_PY'
#!/usr/bin/env python3
# Unio — Copyright (C) 2026 Daniel Mitev
# Public attribution: Daniel Mevit (@danielmevit)
# Original project: https://github.com/danielmevit/unio
# SPDX-License-Identifier: AGPL-3.0-only
# Additional attribution/origin terms: NOTICE (AGPLv3 sections 7(b), 7(c)).
# See LICENSE and NOTICE; distributed without warranty.
"""Managed read-only dashboard: ensure, status and stop. Standard library only.

The canonical copy is embedded by tools/embed-dashboard.py and installed as
CONF_DIR/lib/dashboard.py. It never calls a model and never changes STOP,
lead, bench, policy, grant, auth or cooldown state. It only signals a process
it positively identifies as its own launch, and only through a pidfd.
"""
import argparse
import datetime
import errno
import fcntl
import hashlib
import hmac
import http.client
import json
import os
from pathlib import Path
import re
import secrets
import select
import signal
import stat
import subprocess
import sys
import time

if sys.version_info < (3, 9):
    raise SystemExit('unio dashboard: Python 3.9 or newer is required')

SCHEMA = 1
STATE = 'state.json'
LOCK = 'lock'
LOG = 'server.log'
STATE_LIMIT = 4096
HEALTH_LIMIT = 4096
LOG_LIMIT = 65536
ENVIRON_LIMIT = 1024 * 1024
DEADLINE = 30.0       # whole command, including waiting for a concurrent ensure
READY_SECONDS = 20.0  # one new launch
LOCK_SECONDS = 12.0   # waiting for a concurrent ensure or stop
OPEN_SECONDS = 8.0
STOP_SECONDS = 10.0
NONCE_ENV = 'UNIO_DASHBOARD_LAUNCH'
STATE_FIELDS = {'schema_version', 'status', 'project_hash', 'launch_nonce', 'pid', 'boot_id',
                'start_ticks', 'port', 'version', 'started_at', 'reason'}
HEALTH_FIELDS = {'schema_version', 'managed', 'project_hash', 'launch_nonce', 'version', 'mode'}
REASONS = {'exited_before_ready', 'readiness_timeout', 'health_mismatch'}
HEX64 = re.compile(r'[0-9a-f]{64}')
HEX32 = re.compile(r'[0-9a-f]{32}')
BOOT = re.compile(r'[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}')
VERSION = re.compile(r'[0-9A-Za-z.+_-]{1,64}')
ORIGIN_LINE = re.compile(r'^http://127\.0\.0\.1:([0-9]{1,5}) — ', re.M)
OPENER = ('import sys, webbrowser\n'
          'try:\n    opened = webbrowser.open(sys.argv[1], new=2)\n'
          'except Exception:\n    opened = False\n'
          'sys.exit(0 if opened else 1)\n')


class DashboardError(Exception):
    """A refusal with an owner-facing message; nothing was signalled."""
    def __init__(self, state, message):
        super().__init__(message)
        self.state = state


def unique_object(pairs):
    value = {}
    for key, item in pairs:
        if key in value:
            raise ValueError('duplicate JSON field')
        value[key] = item
    return value


def project_hash(project):
    return hashlib.sha256(str(project).encode('utf-8', 'surrogateescape')).hexdigest()


# ------------------------------------------------------------ private state
class StateDir:
    """coord/dashboard opened without following links; every file op is relative."""

    def __init__(self, project, create):
        self.fd = None
        flags = os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC
        project_fd = os.open(str(project), flags)
        try:
            try:
                coord_fd = os.open('coord', flags, dir_fd=project_fd)
            except OSError as error:
                raise DashboardError('unsafe', 'coord/ is not a real directory') from error
            try:
                try:
                    self.fd = os.open('dashboard', flags, dir_fd=coord_fd)
                except FileNotFoundError:
                    if not create:
                        return
                    try:
                        os.mkdir('dashboard', 0o700, dir_fd=coord_fd)
                    except FileExistsError:
                        pass
                    self.fd = os.open('dashboard', flags, dir_fd=coord_fd)
                except OSError as error:
                    raise DashboardError('unsafe', 'coord/dashboard is not a real directory') from error
            finally:
                os.close(coord_fd)
        finally:
            os.close(project_fd)
        info = os.fstat(self.fd)
        if not stat.S_ISDIR(info.st_mode) or info.st_uid != os.geteuid():
            self.close()
            raise DashboardError('unsafe', 'coord/dashboard is not a private directory owned by this account')
        if stat.S_IMODE(info.st_mode) != 0o700:
            os.fchmod(self.fd, 0o700)

    @property
    def exists(self):
        return self.fd is not None

    def close(self):
        if self.fd is not None:
            os.close(self.fd)
            self.fd = None

    def check_entry(self, name):
        """Return False if absent; refuse anything but a private regular single-link file."""
        try:
            info = os.stat(name, dir_fd=self.fd, follow_symlinks=False)
        except FileNotFoundError:
            return False
        if not stat.S_ISREG(info.st_mode) or info.st_nlink != 1 or info.st_uid != os.geteuid():
            raise DashboardError('unsafe', 'coord/dashboard/' + name + ' is not a private regular file')
        return True

    def open_file(self, name, flags, mode=0o600):
        try:
            fd = os.open(name, flags | os.O_NOFOLLOW | os.O_NONBLOCK | os.O_CLOEXEC, mode, dir_fd=self.fd)
        except OSError as error:
            if error.errno in (errno.ELOOP, errno.ENXIO, errno.EISDIR, errno.EACCES):
                raise DashboardError('unsafe', 'coord/dashboard/' + name + ' is not a private regular file') from error
            raise
        info = os.fstat(fd)
        if not stat.S_ISREG(info.st_mode) or info.st_nlink != 1 or info.st_uid != os.geteuid():
            os.close(fd)
            raise DashboardError('unsafe', 'coord/dashboard/' + name + ' is not a private regular file')
        os.set_blocking(fd, True)
        return fd

    def read_bounded(self, name, limit):
        if not self.exists or not self.check_entry(name):
            return None
        fd = self.open_file(name, os.O_RDONLY)
        try:
            chunks, size = [], 0
            while size <= limit:
                chunk = os.read(fd, limit + 1 - size)
                if not chunk:
                    break
                chunks.append(chunk)
                size += len(chunk)
            return b''.join(chunks)
        finally:
            os.close(fd)

    def write_atomic(self, name, raw):
        self.check_entry(name)
        temporary = '.' + name + '.' + secrets.token_hex(8)
        fd = os.open(temporary, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW | os.O_CLOEXEC,
                     0o600, dir_fd=self.fd)
        try:
            os.write(fd, raw)
            os.fsync(fd)
        except BaseException:
            os.close(fd)
            os.unlink(temporary, dir_fd=self.fd)
            raise
        os.close(fd)
        os.replace(temporary, name, src_dir_fd=self.fd, dst_dir_fd=self.fd)
        os.fsync(self.fd)

    def remove(self, name):
        if self.check_entry(name):
            os.unlink(name, dir_fd=self.fd)
            os.fsync(self.fd)

    def fresh_log(self):
        self.remove(LOG)
        return os.open(LOG, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW | os.O_CLOEXEC,
                       0o600, dir_fd=self.fd)

    def lock(self, deadline):
        fd = self.open_file(LOCK, os.O_RDWR | os.O_CREAT)
        while True:
            try:
                fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
                return fd
            except BlockingIOError:
                if time.monotonic() >= deadline:
                    os.close(fd)
                    raise DashboardError('busy', 'another dashboard command still holds the lock; try again shortly') from None
                time.sleep(0.05)


def parse_state(raw, expected_hash):
    if raw is None:
        return None
    try:
        if len(raw) > STATE_LIMIT:
            raise ValueError('oversized')
        value = json.loads(raw.decode('utf-8'), object_pairs_hook=unique_object)
        if not isinstance(value, dict) or set(value) != STATE_FIELDS:
            raise ValueError('fields')
        integers = ('schema_version', 'pid', 'start_ticks')
        if any(type(value[k]) is not int for k in integers) or value['schema_version'] != SCHEMA:
            raise ValueError('types')
        if value['status'] not in ('running', 'failed') or not 1 < value['pid'] < 2 ** 31 or value['start_ticks'] < 0:
            raise ValueError('values')
        if (type(value['project_hash']) is not str or not HEX64.fullmatch(value['project_hash'])
                or type(value['launch_nonce']) is not str or not HEX32.fullmatch(value['launch_nonce'])
                or type(value['boot_id']) is not str or not BOOT.fullmatch(value['boot_id'])
                or type(value['version']) is not str or not VERSION.fullmatch(value['version'])
                or type(value['started_at']) is not str or len(value['started_at']) > 40):
            raise ValueError('identity')
        port = value['port']
        if port is not None and (type(port) is not int or not 0 < port < 65536):
            raise ValueError('port')
        if value['status'] == 'running':
            if port is None or value['reason'] is not None:
                raise ValueError('running')
        elif value['reason'] not in REASONS:
            raise ValueError('reason')
    except (ValueError, UnicodeDecodeError, RecursionError):
        raise DashboardError('unsafe', 'coord/dashboard/state.json is unreadable or not a dashboard record; '
                             'inspect it and remove it once no dashboard from it is running') from None
    if value['project_hash'] != expected_hash:
        raise DashboardError('unsafe', 'coord/dashboard/state.json belongs to another project path (moved?); '
                             'inspect it and remove it once no dashboard from it is running')
    return value


def encode_state(value):
    raw = (json.dumps(value, sort_keys=True, ensure_ascii=True) + '\n').encode()
    if len(raw) > STATE_LIMIT:
        raise ValueError('dashboard state too large')
    return raw


# --------------------------------------------------------- process identity
def boot_id():
    try:
        with open('/proc/sys/kernel/random/boot_id', 'rb') as handle:
            value = handle.read(64).decode('ascii').strip()
    except (OSError, UnicodeDecodeError):
        return None
    return value if BOOT.fullmatch(value) else None


def start_ticks(pid):
    """Process start time in clock ticks since boot, or None when absent."""
    try:
        with open('/proc/' + str(int(pid)) + '/stat', 'rb') as handle:
            raw = handle.read(4096)
    except (FileNotFoundError, ProcessLookupError):
        return None
    fields = raw[raw.rindex(b')') + 2:].split()
    # Field 22 overall; the list starts at field 3 (state).
    if len(fields) < 20 or fields[0] == b'Z':
        return None
    return int(fields[19])


def environ_has(pid, entry):
    with open('/proc/' + str(int(pid)) + '/environ', 'rb') as handle:
        raw = handle.read(ENVIRON_LIMIT + 1)
    return entry in raw.split(b'\0')


def identify(record):
    """owned: this exact launch; gone: dead or a different process; uncertain otherwise."""
    current_boot = boot_id()
    if current_boot is None:
        return 'uncertain'
    if current_boot != record['boot_id']:
        return 'gone'
    try:
        ticks = start_ticks(record['pid'])
        if ticks is None or ticks != record['start_ticks']:
            return 'gone'
        entry = (NONCE_ENV + '=' + record['launch_nonce']).encode()
        if not environ_has(record['pid'], entry):
            return 'gone'
    except (FileNotFoundError, ProcessLookupError):
        return 'gone'
    except (OSError, ValueError, IndexError):
        return 'uncertain'
    return 'owned'


def health(port, expected_hash, nonce, timeout=2.0):
    """Ask only the metadata endpoint; it never runs the observer or a provider."""
    connection = http.client.HTTPConnection('127.0.0.1', port, timeout=timeout)
    try:
        connection.request('GET', '/api/dashboard', headers={'Host': '127.0.0.1:' + str(port)})
        response = connection.getresponse()
        raw = response.read(HEALTH_LIMIT + 1)
        if response.status != 200 or len(raw) > HEALTH_LIMIT:
            return None
        value = json.loads(raw.decode('utf-8'), object_pairs_hook=unique_object)
    except (OSError, ValueError, UnicodeDecodeError, http.client.HTTPException):
        return None
    finally:
        connection.close()
    if (not isinstance(value, dict) or set(value) != HEALTH_FIELDS or value['schema_version'] != SCHEMA
            or value['managed'] is not True or value['mode'] != 'read-only'
            or value['project_hash'] != expected_hash or type(value['launch_nonce']) is not str
            or not hmac.compare_digest(value['launch_nonce'].encode(), nonce.encode())
            or type(value['version']) is not str or not VERSION.fullmatch(value['version'])):
        return None
    return value


def url_for(port):
    return 'http://127.0.0.1:' + str(port)


def now():
    return datetime.datetime.now(datetime.timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ')


# ------------------------------------------------------------------ actions
class Dashboard:
    def __init__(self, project, engine, browser_dir, version):
        self.project, self.engine, self.browser_dir, self.version = project, engine, browser_dir, version
        self.hash = project_hash(project)
        self.start = time.monotonic()

    def remaining(self):
        return self.start + DEADLINE - time.monotonic()

    def observe(self, directory):
        """Classify recorded state without starting, writing or signalling anything."""
        record = parse_state(directory.read_bounded(STATE, STATE_LIMIT), self.hash)
        if record is None:
            return 'none', None, None
        if record['status'] == 'failed':
            return 'failed', record, None
        identity = identify(record)
        if identity == 'gone':
            return 'stale', record, None
        if identity == 'uncertain':
            return 'uncertain', record, None
        document = health(record['port'], self.hash, record['launch_nonce'])
        return ('running' if document else 'unhealthy'), record, document

    def status(self):
        directory = StateDir(self.project, create=False)
        try:
            state, record, document = self.observe(directory)
        finally:
            directory.close()
        result = dict(action='status', state=state)
        if record is not None and state in ('running', 'unhealthy'):
            result.update(pid=record['pid'])
        if state == 'running':
            result.update(url=url_for(record['port']), version=document['version'])
        if state == 'failed':
            result.update(reason=record['reason'])
        return result

    def ensure(self, open_browser):
        directory = StateDir(self.project, create=True)
        lock = None
        try:
            lock = directory.lock(self.start + LOCK_SECONDS)
            state, record, document = self.observe(directory)
            if state == 'running':
                result = dict(action='ensure', state='reused', url=url_for(record['port']),
                              pid=record['pid'], version=document['version'],
                              browser='not_new' if open_browser else 'not_requested')
                return result
            if state == 'unhealthy':
                raise DashboardError('unhealthy', 'the managed dashboard process ' + str(record['pid'])
                                     + ' is running but does not answer as this project\'s dashboard; '
                                     'run unio dashboard stop, then unio dashboard ensure')
            if state == 'uncertain':
                raise DashboardError('uncertain', 'cannot confirm whether recorded process '
                                     + str(record['pid']) + ' is this dashboard; nothing was started or signalled')
            result = self.launch(directory)
            result['previous'] = state
            if open_browser:
                result['browser'] = open_url(result['url'], self.environment(None))
            else:
                result['browser'] = 'not_requested'
            return result
        finally:
            if lock is not None:
                os.close(lock)
            directory.close()

    def environment(self, nonce):
        environment = {k: v for k, v in os.environ.items() if k != NONCE_ENV}
        if nonce is not None:
            environment[NONCE_ENV] = nonce
        return environment

    def launch(self, directory):
        current_boot = boot_id()
        if current_boot is None or not hasattr(os, 'pidfd_open'):
            raise DashboardError('uncertain', 'process identity is unavailable on this system (Linux /proc and pidfd are required)')
        nonce = secrets.token_hex(16)
        log = directory.fresh_log()
        try:
            command = [sys.executable, '-E', '-s', '-B', str(self.browser_dir / 'launcher.py'),
                       str(self.engine), str(self.project), self.version]
            # The child never inherits the caller's pipes: a captured parent returns promptly.
            child = subprocess.Popen(command, cwd=str(self.project), env=self.environment(nonce),
                                     stdin=subprocess.DEVNULL, stdout=log, stderr=subprocess.STDOUT,
                                     close_fds=True, start_new_session=True)
        finally:
            os.close(log)
        ticks = start_ticks(child.pid) or 0
        record = dict(schema_version=SCHEMA, status='running', project_hash=self.hash, launch_nonce=nonce,
                      pid=child.pid, boot_id=current_boot, start_ticks=ticks, port=None,
                      version=self.version, started_at=now(), reason=None)
        reason, port, document = self.await_ready(directory, child, nonce)
        if reason is None:
            record['port'] = port
            directory.write_atomic(STATE, encode_state(record))
            return dict(action='ensure', state='started', url=url_for(port), pid=child.pid,
                        version=document['version'])
        # Unreaped, so the PID and its new session still belong to this launch.
        try:
            os.killpg(child.pid, signal.SIGKILL)
        except (ProcessLookupError, PermissionError):
            pass
        try:
            child.wait(timeout=5)
        except subprocess.TimeoutExpired:
            pass
        record.update(status='failed', port=port, reason=reason)
        directory.write_atomic(STATE, encode_state(record))
        raise DashboardError('failed', 'the new dashboard did not become ready (' + reason
                             + '); its own process was stopped. Startup output: coord/dashboard/' + LOG)

    def await_ready(self, directory, child, nonce):
        deadline = time.monotonic() + max(1.0, min(READY_SECONDS, self.remaining() - 1))
        port = None
        while time.monotonic() < deadline:
            if exited_unreaped(child.pid):
                return 'exited_before_ready', port, None
            if port is None:
                try:
                    raw = directory.read_bounded(LOG, LOG_LIMIT) or b''
                except DashboardError:
                    raise
                except OSError:
                    raw = b''  # Some mounts briefly fail reads during a write; retry until the deadline.
                match = ORIGIN_LINE.search(raw[:LOG_LIMIT].decode('utf-8', 'replace'))
                if match and 0 < int(match.group(1)) < 65536:
                    port = int(match.group(1))
            if port is not None:
                document = health(port, self.hash, nonce, timeout=1.0)
                if document is not None:
                    return None, port, document
            time.sleep(0.05)
        return ('readiness_timeout' if port is None else 'health_mismatch'), port, None

    def stop(self):
        directory = StateDir(self.project, create=False)
        if not directory.exists:
            return dict(action='stop', state='none')
        lock = None
        try:
            lock = directory.lock(self.start + DEADLINE - STOP_SECONDS - 7)
            record = parse_state(directory.read_bounded(STATE, STATE_LIMIT), self.hash)
            if record is None:
                return dict(action='stop', state='none')
            if record['status'] == 'failed':
                directory.remove(STATE)
                return dict(action='stop', state='failed', reason=record['reason'])
            if not hasattr(os, 'pidfd_open'):
                raise DashboardError('uncertain', 'this system cannot signal a process by pidfd; nothing was signalled')
            try:
                pidfd = os.pidfd_open(record['pid'])
            except ProcessLookupError:
                directory.remove(STATE)
                return dict(action='stop', state='stale')
            try:
                # Identify after pinning: a reused PID fails here, a pinned exit cannot be re-targeted.
                identity = identify(record)
                if identity == 'gone':
                    directory.remove(STATE)
                    return dict(action='stop', state='stale')
                if identity != 'owned':
                    raise DashboardError('uncertain', 'cannot confirm that process ' + str(record['pid'])
                                         + ' is this dashboard; nothing was signalled')
                healthy = health(record['port'], self.hash, record['launch_nonce']) is not None
                if not terminate(pidfd):
                    raise DashboardError('uncertain', 'managed dashboard process ' + str(record['pid'])
                                         + ' did not exit; state kept')
            finally:
                os.close(pidfd)
            directory.remove(STATE)
            return dict(action='stop', state='stopped', pid=record['pid'], was_healthy=healthy)
        finally:
            if lock is not None:
                os.close(lock)
            directory.close()


def exited_unreaped(pid):
    """Observe a child's exit without reaping it, so its PID stays ours for cleanup."""
    try:
        return os.waitid(os.P_PID, pid, os.WEXITED | os.WNOHANG | os.WNOWAIT) is not None
    except ChildProcessError:
        return True


def exited(pidfd, seconds):
    readable, _, _ = select.select([pidfd], [], [], max(0.0, seconds))
    return bool(readable)


def terminate(pidfd):
    try:
        signal.pidfd_send_signal(pidfd, signal.SIGTERM)
    except ProcessLookupError:
        return True
    if exited(pidfd, STOP_SECONDS):
        return True
    try:
        signal.pidfd_send_signal(pidfd, signal.SIGKILL)
    except ProcessLookupError:
        return True
    return exited(pidfd, 5)


def open_url(url, environment):
    """Ask the desktop once from a detached helper that cannot hold the caller's pipes."""
    try:
        opener = subprocess.Popen([sys.executable, '-I', '-S', '-B', '-c', OPENER, url], env=environment,
                                  stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL,
                                  stderr=subprocess.DEVNULL, close_fds=True, start_new_session=True)
    except OSError:
        return 'not_opened'
    try:
        return 'opened' if opener.wait(timeout=OPEN_SECONDS) == 0 else 'not_opened'
    except subprocess.TimeoutExpired:
        return 'unconfirmed'


# ---------------------------------------------------------------- reporting
MESSAGES = {
    'none': 'No managed dashboard is recorded for this project. A foreground "unio browser" is not tracked.',
    'stale': 'The recorded dashboard process is gone or was replaced by another process; it was not signalled.',
    'failed': 'The last managed dashboard launch failed',
    'unhealthy': 'The managed dashboard process is running but does not answer as this project\'s dashboard.',
    'uncertain': 'Cannot confirm the recorded dashboard process identity; nothing was signalled.',
}
BROWSER = {
    'opened': 'Opened in the desktop browser.',
    'not_opened': 'No desktop browser could be opened; open the link above manually.',
    'unconfirmed': 'Desktop opening was requested but not confirmed; open the link above manually.',
    'not_new': 'Already running, so no new browser tab was opened.',
}


def render(result, project):
    lines = []
    state = result['state']
    if result.get('url'):
        lines.append('Unio dashboard (read-only): ' + result['url'])
    if state == 'started':
        lines.append('Started a new managed dashboard for ' + str(project) + '.')
        if result.get('previous') in ('stale', 'failed'):
            lines.append('The earlier record was ' + result['previous'] + '; no older process was signalled.')
    elif state == 'reused':
        lines.append('Reusing the running managed dashboard for ' + str(project) + '.')
    elif state == 'running':
        lines.append('Running (process ' + str(result['pid']) + ', Unio ' + result['version'] + ') for ' + str(project) + '.')
    elif state == 'stopped':
        lines.append('Stopped managed dashboard process ' + str(result['pid']) + '. Workers and STOP were not touched.')
    elif state == 'failed':
        lines.append(MESSAGES['failed'] + ' (' + result['reason'] + ').'
                     + (' Its record was cleared.' if result['action'] == 'stop' else ''))
    elif state == 'none' and result['action'] == 'stop':
        lines.append('No managed dashboard is recorded for this project; nothing was signalled.')
    elif state == 'stale' and result['action'] == 'stop':
        lines.append(MESSAGES['stale'] + ' Its record was cleared.')
    else:
        lines.append(MESSAGES.get(state, state))
    if result.get('browser') in BROWSER:
        lines.append(BROWSER[result['browser']])
    if result.get('version') and result['version'] != result.get('installed') and state in ('reused', 'running'):
        lines.append('It runs Unio ' + result['version'] + ' while ' + result['installed']
                     + ' is installed; use stop, then ensure, to restart it.')
    return '\n'.join(lines)


def select_project(value):
    project = Path(value).absolute()
    try:
        real = project.is_symlink() is False and project.resolve(strict=True) == project
    except OSError:
        real = False
    if not real or any(not (project / part).is_dir() or (project / part).is_symlink()
                       for part in ('repo', 'coord', 'wt')):
        raise DashboardError('invalid', 'project must be a real enclosing Unio workspace (repo/, coord/, wt/)')
    return project


EXIT = {'started': 0, 'reused': 0, 'running': 0, 'stopped': 0, 'none': 3, 'stale': 3, 'failed': 3}


def main(argv=None):
    argv = list(sys.argv[1:] if argv is None else argv)
    if len(argv) < 4:
        raise SystemExit('unio dashboard: run through the installed unio command')
    engine, browser_dir, version, default_project = argv[:4]
    parser = argparse.ArgumentParser(
        prog='unio dashboard',
        description='Start or reuse a detached, local, read-only browser dashboard for one project.')
    parser.add_argument('action', nargs='?', choices=('ensure', 'status', 'stop'), default='ensure',
                        help='ensure (default) starts or reuses it; status only reports; stop ends it')
    parser.add_argument('--project', help='enclosing workspace with repo/, coord/, wt/ (inferred inside a workspace)')
    parser.add_argument('--open-browser', action='store_true', help='ensure only: ask the desktop to open a newly started dashboard')
    parser.add_argument('--json', action='store_true', help='print one JSON document')
    options = parser.parse_args(argv[4:])
    if options.open_browser and options.action != 'ensure':
        parser.error('--open-browser applies to ensure only')
    if not VERSION.fullmatch(version):
        raise SystemExit('unio dashboard: invalid installed version')
    selected = options.project if options.project is not None else default_project
    try:
        if not selected:
            raise DashboardError('invalid', 'no Unio workspace (coord/ and wt/) found here; pass --project PATH')
        project = select_project(selected)
        dashboard = Dashboard(project, Path(engine).absolute(), Path(browser_dir).absolute(), version)
        result = getattr(dashboard, options.action)(**({'open_browser': options.open_browser}
                                                        if options.action == 'ensure' else {}))
        result['installed'] = version
        code = 0 if options.action == 'stop' and result['state'] in ('none', 'stale', 'failed') else EXIT.get(result['state'], 1)
    except DashboardError as error:
        result = dict(action=options.action, state=error.state, error=str(error))
        code = 2 if error.state == 'invalid' else 1
        project = None
    except OSError as error:
        result = dict(action=options.action, state='unsafe',
                      error='dashboard state is unavailable (' + (os.strerror(error.errno) if error.errno else 'I/O error') + ')')
        code, project = 1, None
    if options.json:
        result['schema_version'] = SCHEMA
        print(json.dumps(result, sort_keys=True, ensure_ascii=True))
    elif 'error' in result:
        print('unio dashboard: ' + result['error'], file=sys.stderr)
    else:
        print(render(result, project), flush=True)
    return code


if __name__ == '__main__':
    sys.exit(main())
